def chunk(s,a,b):
    i=s.index(a);j=s.index(b,i)+len(b)
    return s[i:j]
def add(id,p,place,c,h,f,evidence,kind,ac=False,ah=True,confidence='high',consequential=False):
    for label,s,t in [('C',C,c),('H',H,h),('final',F,f)]:
        assert t in s,(id,label,repr(t))
    cats={'misread symbol or index':1,'misread word':2,'omission':3,'drawing or diagram':4,'readable ink left as \\ill{}':5,'insertion or placement':6,'deletion state (struck given live or live given struck)':7,'abbreviation expanded or spelling modernised':8,'text not on the page':9,'other':10}
    changes.append(dict(id=id,place=place,c=c,h=h,final=f,evidence=evidence,crop=f'crops/150_scan005_{p}.png',box=BOX[p],confidence=confidence,kind=kind,against_c=ac,against_h=ah,marked_in_h=('\\uncertain' in h or '\\ill' in h),consequential=consequential,error_category=cats[kind]))

